import React, { useState, useEffect } from 'react';
import axios from 'axios';
import StoryViewer from './StoryViewer';
import { Plus } from 'lucide-react';

const Stories = () => {
  const [stories, setStories] = useState([]);
  const [viewingStory, setViewingStory] = useState(null);
  const [currentIndex, setCurrentIndex] = useState(0);
  const [uploading, setUploading] = useState(false);

  useEffect(() => {
    fetchStories();
  }, []);

  const fetchStories = async () => {
    try {
      const res = await axios.get('/stories/feed');
      setStories(res.data);
    } catch (err) {
      console.error(err);
    }
  };

  const openStory = (userStories, index) => {
    setViewingStory(userStories);
    setCurrentIndex(index);
  };

  const closeStory = () => {
    setViewingStory(null);
  };

  const handleAddStory = async (e) => {
    const file = e.target.files[0];
    if (!file) return;

    setUploading(true);
    const formData = new FormData();
    formData.append('image', file);

    try {
      await axios.post('/stories', formData, {
        headers: { 'Content-Type': 'multipart/form-data' }
      });
      fetchStories();
    } catch (err) {
      alert(err.response?.data?.error || 'Failed to upload story');
    } finally {
      setUploading(false);
    }
  };

  return (
    <>
      <div style={{ 
        background: '#fff', 
        border: '1px solid #dbdbdb', 
        borderRadius: '8px', 
        padding: '15px', 
        marginBottom: '20px',
        overflowX: 'auto',
        whiteSpace: 'nowrap',
        display: 'flex',
        alignItems: 'center'
      }}>
        {/* Upload New Story Button */}
        <label style={{ display: 'inline-block', margin: '0 10px', cursor: 'pointer', textAlign: 'center', flexShrink: 0 }}>
          <div style={{
            width: '64px',
            height: '64px',
            borderRadius: '50%',
            border: '2px dashed #0095f6',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            background: '#f0f9ff',
            color: '#0095f6'
          }}>
            <Plus size={24} />
          </div>
          <span style={{ fontSize: '12px', marginTop: '5px', display: 'block' }}>
            {uploading ? 'Posting...' : 'Add Story'}
          </span>
          <input type="file" accept="image/*" onChange={handleAddStory} style={{ display: 'none' }} disabled={uploading} />
        </label>

        {stories.map((userStory, idx) => (
          <div 
            key={userStory.user.id || idx} 
            onClick={() => openStory(userStory, idx)}
            style={{ 
              display: 'inline-block', 
              margin: '0 10px', 
              cursor: 'pointer',
              textAlign: 'center',
              flexShrink: 0
            }}
          >
            <div style={{ 
              width: '70px', 
              height: '70px', 
              borderRadius: '50%', 
              background: 'linear-gradient(45deg, #f09433, #e6683c, #dc2743, #cc2366, #bc1888)',
              padding: '3px'
            }}>
              <img 
                src={userStory.user.profilePic || 'https://via.placeholder.com/150'} 
                alt={userStory.user.username}
                style={{ 
                  width: '64px', 
                  height: '64px', 
                  borderRadius: '50%', 
                  border: '3px solid #fff',
                  objectFit: 'cover'
                }}
              />
            </div>
            <p style={{ fontSize: '12px', marginTop: '5px', maxWidth: '70px', overflow: 'hidden', textOverflow: 'ellipsis' }}>
              {userStory.user.username}
            </p>
          </div>
        ))}
      </div>

      {viewingStory && (
        <StoryViewer 
          stories={viewingStory.stories}
          user={viewingStory.user}
          currentIndex={currentIndex}
          onClose={closeStory}
        />
      )}
    </>
  );
};

export default Stories;
